frontend/src/tests/build.spec.ts<pre><code>import test from "@playwright/test";
import { BuildPage } from "./pages/build.page";
import { LoginPage } from "./pages/login.page";
import { getTestUser } from "./utils/auth";
import { hasUrl } from "./utils/assertion";

// Reason Ignore: admonishment is in the wrong place visually with correct prettier rules
// prettier-ignore
test.describe("Build", () =&gt; { //(1)!
  let buildPage: BuildPage; //(2)!

  // Reason Ignore: admonishment is in the wrong place visually with correct prettier rules
  // prettier-ignore
  test.beforeEach(async ({ page }) =&gt; { //(3)! ts-ignore
    const loginPage = new LoginPage(page);
    const testUser = await getTestUser();

    buildPage = new BuildPage(page);

    // Start each test with login using worker auth
    await page.goto("/login"); //(4)!
    await loginPage.login(testUser.email, testUser.password);
    await hasUrl(page, "/marketplace"); //(5)!
    await buildPage.navbar.clickBuildLink();
    await hasUrl(page, "/build");
    await buildPage.closeTutorial();
  });

  // Helper function to add blocks starting with a specific letter, split into parts for parallelization
  async function addBlocksStartingWithSplit(letter: string, part: number, totalParts: number): Promise&lt;void&gt; {
    const blockIdsToSkip = await buildPage.getBlocksToSkip();
    const blockTypesToSkip = ["Input", "Output", "Agent", "AI"];
    const targetLetter = letter.toLowerCase();

    const allBlocks = await buildPage.getFilteredBlocksFromAPI(block =&gt; 
      block.name[0].toLowerCase() === targetLetter &amp;&amp;
      !blockIdsToSkip.includes(block.id) &amp;&amp; 
      !blockTypesToSkip.includes(block.type)
    );

    const blocksToAdd = allBlocks.filter((_, index) =&gt; 
      index % totalParts === (part - 1)
    );

    console.log(`Adding ${blocksToAdd.length} blocks starting with "${letter}" (part ${part}/${totalParts})`);

    for (const block of blocksToAdd) {
      await buildPage.addBlock(block);
    }
  }

  // Reason Ignore: admonishment is in the wrong place visually with correct prettier rules
  // prettier-ignore
  test("user can add a block", async ({ page: _page }) =&gt; { //(6)!
    await buildPage.openBlocksPanel(); //(10)!
    const blocks = await buildPage.getFilteredBlocksFromAPI(block =&gt; block.name[0].toLowerCase() === "a");
    const block = blocks.at(-1);
    if (!block) throw new Error("No block found");

    await buildPage.addBlock(block); //(11)!
    await buildPage.closeBlocksPanel(); //(12)!
    await buildPage.hasBlock(block); //(13)!
  });
});
</code></pre> <ol> <li><code>test.describe</code> 用于将测试分组。此处用于将构建页面的所有测试归为一组。</li> <li><code>let buildPage: BuildPage;</code> 用于创建构建页面的新实例。</li> <li><code>test.beforeEach</code> 用于在每个测试前运行代码。此处用于在每个测试前登录用户。<code>page</code> 是从 fixture 传入的页面对象，<code>loginPage</code> 是登录页面的页面对象，<code>testUser</code> 是从 fixture 传入的用户对象。fixture 用于处理身份验证和其他常见的共享状态任务。</li> <li><code>await page.goto("/login");</code> 用于导航到登录页面。</li> <li><code>await test.expect(page).toHaveURL("/");</code> 用于检查页面是否已导航到主页（即用户已登录）。</li> <li><code>test("user can add a block", async ({ page }) =&gt; {</code> 用于定义新测试。</li> <li><code>await test.expect(buildPage.isLoaded()).resolves.toBeTruthy();</code> 用于检查构建页面是否已加载。这可以合理地在 <code>test.beforeEach</code> 中完成，但为了清晰起见在此处完成，因为该测试套件中还有其他测试。</li> <li><code>await test.expect(page).toHaveURL(new RegExp("/.*build"));</code> 用于检查页面是否已导航到构建页面。</li> <li><code>await buildPage.closeTutorial();</code> 用于关闭构建页面上的教程。值得注意的是，这个包装函数实际上并不关心教程是否已打开，它确保教程**将**被关闭。这是一个有用且常见的模式，用于确保某件事会被完成，而不关心它是否已经完成。它可以用于切换设置、关闭/打开侧边栏等场景。</li> <li><code>await buildPage.openBlocksPanel();</code> 用于打开构建页面上的积木面板，其方式与 <code>closeTutorial</code> 函数描述相同。</li> <li><code>await buildPage.addBlock(block);</code> 用于将特定积木添加到构建页面。这是另一个可以在代码行内完成的实用函数，但由于页面对象模式的工作方式，我们应该将它们保留在页面对象中。（它也有助于保持测试代码更清晰，并在其他测试中使用）</li> <li><code>await buildPage.closeBlocksPanel();</code> 用于关闭构建页面上的积木面板。</li> <li><code>await test.expect(buildPage.hasBlock(block)).resolves.toBeTruthy();</code> 用于检查积木是否已添加到构建页面。</li> </ol>
